// Extract properties needing contact enrichment
const inputData = $input.first().json;
const requestData = inputData.body || inputData;

try {
  if (!requestData.batchId && !requestData.propertyIds) {
    throw new Error('Either batchId or propertyIds is required');
  }

  console.log('Starting contact discovery workflow');

  // In production, fetch from database
  // For demo, simulate properties without contacts
  const properties = [];

  for (let i = 0; i < 20; i++) {
    properties.push({
      id: `prop-${i}`,
      address: `${1000 + i} Main St, Austin, TX 78701`,
      ownerName: `${['Smith', 'Johnson', 'Williams', 'Brown', 'Davis'][i % 5]} Properties LLC`,
      entityResolution: {
        llcName: `${['Smith', 'Johnson', 'Williams', 'Brown', 'Davis'][i % 5]} Properties LLC`,
        keyPerson: {
          name: `${['John', 'Jane', 'Michael', 'Sarah', 'David'][i % 5]} ${['Smith', 'Johnson', 'Williams', 'Brown', 'Davis'][i % 5]}`,
          title: ['CEO', 'Managing Partner', 'President'][i % 3]
        }
      },
      hasContact: false
    });
  }

  return properties.map(prop => ({ json: prop }));

} catch (error) {
  console.error('Input validation error:', error.message);
  throw error;
}

// Step 1: Extract company domain from LLC name
const property = $input.item.json;
const llcName = property.entityResolution.llcName;

console.log(`Discovering contacts for ${llcName}`);

// Extract potential company name (remove LLC, Properties, etc.)
const cleanName = llcName
  .replace(/\bLLC\b/gi, '')
  .replace(/\bProperties\b/gi, '')
  .replace(/\bInvestments\b/gi, '')
  .replace(/\bHoldings\b/gi, '')
  .replace(/\bGroup\b/gi, '')
  .trim();

// Generate potential domain names
const potentialDomains = [
  `${cleanName.toLowerCase().replace(/\s+/g, '')}.com`,
  `${cleanName.toLowerCase().replace(/\s+/g, '-')}.com`,
  `${cleanName.toLowerCase().replace(/\s+/g, '')}properties.com`,
  `${cleanName.toLowerCase().replace(/\s+/g, '')}investments.com`
];

// Simulate domain validation (in production, use DNS lookup)
const validDomain = potentialDomains[0];

return [{
  json: {
    ...property,
    companyDomain: validDomain,
    potentialDomains: potentialDomains,
    discoveryStep: 'domain-found'
  }
}];

// Step 2: Email pattern generation and discovery
const property = $input.item.json;
const keyPerson = property.entityResolution.keyPerson;
const domain = property.companyDomain;

const nameParts = keyPerson.name.split(' ');
const firstName = nameParts[0].toLowerCase();
const lastName = nameParts[nameParts.length - 1].toLowerCase();
const firstInitial = firstName.charAt(0);
const lastInitial = lastName.charAt(0);

// Generate email permutations
const emailPatterns = [
  `${firstName}.${lastName}@${domain}`,
  `${firstName}${lastName}@${domain}`,
  `${firstInitial}${lastName}@${domain}`,
  `${firstName}${lastInitial}@${domain}`,
  `${firstName}@${domain}`,
  `${lastName}@${domain}`,
  `${firstInitial}.${lastName}@${domain}`,
  `${firstName}_${lastName}@${domain}`
];

// Simulate Hunter.io / Apollo.io API call
// In production, call actual email discovery APIs
const discoveredEmails = [];

for (const email of emailPatterns) {
  // Simulate 40% success rate for email discovery
  if (Math.random() > 0.6) {
    discoveredEmails.push({
      email: email,
      source: ['Hunter.io', 'Apollo.io', 'Clearbit'][Math.floor(Math.random() * 3)],
      confidence: Math.floor(Math.random() * 30) + 70,
      verified: false,
      pattern: email.split('@')[0]
    });
    break; // Use first successful pattern
  }
}

// Generic company emails
const genericEmails = [
  `info@${domain}`,
  `contact@${domain}`,
  `admin@${domain}`
];

if (discoveredEmails.length === 0) {
  // Fallback to generic email
  discoveredEmails.push({
    email: genericEmails[0],
    source: 'Generic Pattern',
    confidence: 50,
    verified: false,
    isGeneric: true
  });
}

console.log(`Found ${discoveredEmails.length} potential emails`);

return [{
  json: {
    ...property,
    discoveredEmails: discoveredEmails,
    emailPatterns: emailPatterns,
    discoveryStep: 'emails-found'
  }
}];

// Step 3: Phone number discovery
const property = $input.item.json;
const keyPerson = property.entityResolution.keyPerson;

console.log(`Finding phone numbers for ${keyPerson.name}`);

// Simulate TrueCaller API / NumVerify API calls
// In production, call actual phone lookup APIs

const discoveredPhones = [];

// Simulate 60% success rate for phone discovery
if (Math.random() > 0.4) {
  const areaCode = ['512', '737', '214', '469', '713', '281'][Math.floor(Math.random() * 6)];
  const phoneNumber = `+1-${areaCode}-${Math.floor(Math.random() * 900) + 100}-${Math.floor(Math.random() * 9000) + 1000}`;

  discoveredPhones.push({
    number: phoneNumber,
    type: ['mobile', 'office'][Math.floor(Math.random() * 2)],
    source: ['TrueCaller', 'NumVerify', 'Public Records'][Math.floor(Math.random() * 3)],
    confidence: Math.floor(Math.random() * 20) + 75,
    verified: false,
    carrier: ['AT&T', 'Verizon', 'T-Mobile'][Math.floor(Math.random() * 3)]
  });
}

// Office number (if available)
if (Math.random() > 0.5) {
  const officePhone = `+1-512-${Math.floor(Math.random() * 900) + 100}-${Math.floor(Math.random() * 9000) + 1000}`;
  discoveredPhones.push({
    number: officePhone,
    type: 'office',
    source: 'Business Directory',
    confidence: 85,
    verified: false
  });
}

console.log(`Found ${discoveredPhones.length} phone numbers`);

return [{
  json: {
    ...property,
    discoveredPhones: discoveredPhones,
    discoveryStep: 'phones-found'
  }
}];

// Step 4: LinkedIn profile matching via Proxycurl API
const property = $input.item.json;
const keyPerson = property.entityResolution.keyPerson;
const companyName = property.entityResolution.llcName;

console.log(`Searching LinkedIn for ${keyPerson.name} at ${companyName}`);

// Simulate Proxycurl API call
// In production, call actual Proxycurl API

const linkedInProfile = {
  found: Math.random() > 0.3, // 70% success rate
  profileUrl: null,
  headline: null,
  experience: [],
  email: null,
  phone: null
};

if (linkedInProfile.found) {
  const nameSlug = keyPerson.name.toLowerCase().replace(/\s+/g, '-');
  linkedInProfile.profileUrl = `https://linkedin.com/in/${nameSlug}-${Math.floor(Math.random() * 9999)}`;
  linkedInProfile.headline = `${keyPerson.title} at ${companyName}`;
  linkedInProfile.experience = [
    {
      title: keyPerson.title,
      company: companyName,
      duration: `${Math.floor(Math.random() * 10) + 1} years`
    }
  ];

  // Sometimes LinkedIn provides contact info
  if (Math.random() > 0.7) {
    linkedInProfile.email = property.discoveredEmails[0]?.email || null;
  }

  if (Math.random() > 0.8) {
    linkedInProfile.phone = property.discoveredPhones[0]?.number || null;
  }
}

return [{
  json: {
    ...property,
    linkedInProfile: linkedInProfile,
    discoveryStep: 'linkedin-enriched'
  }
}];

// Step 5: Dun & Bradstreet financial history
const property = $input.item.json;
const companyName = property.entityResolution.llcName;

console.log(`Fetching D&B data for ${companyName}`);

// Simulate D&B API call
// In production, call actual D&B API

const dnbData = {
  found: Math.random() > 0.4, // 60% success rate
  dunsNumber: null,
  creditScore: null,
  annualRevenue: null,
  employeeCount: null,
  riskAssessment: null,
  paymentHistory: null,
  yearsInBusiness: null
};

if (dnbData.found) {
  dnbData.dunsNumber = `${Math.floor(Math.random() * 900000000) + 100000000}`;
  dnbData.creditScore = Math.floor(Math.random() * 40) + 60; // 60-100
  dnbData.annualRevenue = `$${Math.floor(Math.random() * 10) + 1}M - $${Math.floor(Math.random() * 50) + 10}M`;
  dnbData.employeeCount = Math.floor(Math.random() * 50) + 5;
  dnbData.riskAssessment = ['Low', 'Low-Medium', 'Medium'][Math.floor(Math.random() * 3)];
  dnbData.paymentHistory = ['Satisfactory', 'Good', 'Excellent'][Math.floor(Math.random() * 3)];
  dnbData.yearsInBusiness = Math.floor(Math.random() * 20) + 3;
}

return [{
  json: {
    ...property,
    dnbData: dnbData,
    discoveryStep: 'dnb-enriched'
  }
}];

// Consolidate all discovered contact information
const property = $input.item.json;

const contactData = {
  propertyId: property.id,
  ownerName: property.ownerName,
  keyPerson: property.entityResolution.keyPerson,

  // Contact information
  emails: property.discoveredEmails || [],
  phones: property.discoveredPhones || [],

  // Social profiles
  linkedIn: property.linkedInProfile || {},

  // Business intelligence
  companyDomain: property.companyDomain,
  dnbData: property.dnbData || {},

  // Discovery metadata
  discoveryComplete: true,
  discoveredAt: new Date().toISOString(),
  totalContactsFound: (property.discoveredEmails?.length || 0) + (property.discoveredPhones?.length || 0),

  // Quality score
  contactQuality: calculateQualityScore(property)
};

function calculateQualityScore(prop) {
  let score = 0;

  // Email quality
  const emails = prop.discoveredEmails || [];
  if (emails.length > 0 && !emails[0].isGeneric) {
    score += 40;
  } else if (emails.length > 0) {
    score += 20;
  }

  // Phone quality
  const phones = prop.discoveredPhones || [];
  if (phones.length > 0) {
    score += 30;
  }

  // LinkedIn presence
  if (prop.linkedInProfile?.found) {
    score += 20;
  }

  // D&B data
  if (prop.dnbData?.found) {
    score += 10;
  }

  return score;
}

const qualityScore = contactData.contactQuality;
let qualityTier = 'Low';
if (qualityScore >= 80) qualityTier = 'Excellent';
else if (qualityScore >= 60) qualityTier = 'Good';
else if (qualityScore >= 40) qualityTier = 'Fair';

contactData.qualityTier = qualityTier;

console.log(`Contact discovery complete. Quality: ${qualityTier} (${qualityScore}/100)`);

return [{ json: contactData }];

// Prepare batch for email verification
const contacts = $input.all().map(item => item.json);

// Extract all emails for verification
const emailsForVerification = [];

contacts.forEach(contact => {
  contact.emails.forEach(emailData => {
    emailsForVerification.push({
      propertyId: contact.propertyId,
      email: emailData.email,
      source: emailData.source,
      confidence: emailData.confidence,
      personName: contact.keyPerson.name
    });
  });
});

const result = {
  batchId: `verification-${Date.now()}`,
  totalContacts: contacts.length,
  totalEmails: emailsForVerification.length,
  contacts: contacts,
  emailsForVerification: emailsForVerification,
  timestamp: new Date().toISOString(),
  nextStep: 'email-verification'
};

console.log(`Prepared ${emailsForVerification.length} emails for verification`);

return [{ json: result }];
